#!/usr/bin/env node
// Usage:
//   git log --format='%h%x09%an%x09%s' v1.2.0..HEAD | node cli.js - --version v1.3.0
//   node cli.js examples/git-log.txt --version v1.3.0 --repo https://github.com/acme/shop [--all]
const fs = require("fs");
const { draft } = require("./src/notes");

const argv = process.argv.slice(2);
const opt = (name) => {
  const i = argv.indexOf(name);
  return i >= 0 ? argv[i + 1] : undefined;
};
const valued = new Set(["--version", "--repo", "--date"]);
const file = argv.find((a, i) => !a.startsWith("--") && !valued.has(argv[i - 1]));

if (!file) {
  console.error("Usage: node cli.js <git-log.txt | -> [--version v1.3.0] [--date 2026-10-15] [--repo URL] [--all]");
  process.exit(2);
}

const text = fs.readFileSync(file === "-" ? 0 : file, "utf8");
console.log(
  draft(text.split(/\r?\n/), {
    version: opt("--version"),
    date: opt("--date") || new Date().toISOString().slice(0, 10),
    repoUrl: (opt("--repo") || "").replace(/\/$/, ""),
    all: argv.includes("--all"),
  })
);

// Drafts release notes from `git log --format='%h%x09%an%x09%s'` output.
// Conventional Commit types are grouped into sections a user cares about;
// everything else is counted, and shown only with { all: true }.

const SECTIONS = [
  ["breaking", "⚠️ Breaking changes"],
  ["feat", "Features"],
  ["fix", "Fixes"],
  ["perf", "Performance"],
  ["other", "Other changes"],
];

const CONVENTIONAL = /^(\w+)(?:\(([^)]+)\))?(!)?:\s*(.+)$/;

function parseLine(line) {
  const [hash, author, ...rest] = line.split("\t");
  const raw = rest.join("\t").trim();
  if (!hash || !author || !raw) return null;
  if (/^Merge (pull request|branch|remote-tracking)/.test(raw)) return null;

  const pr = raw.match(/\(#(\d+)\)\s*$/);
  const text = pr ? raw.slice(0, pr.index).trim() : raw;
  const m = text.match(CONVENTIONAL);
  if (!m) return { hash, author: author.trim(), type: null, scope: null, breaking: false, subject: text, pr: pr ? Number(pr[1]) : null };

  const type = m[1].toLowerCase();
  if (type === "chore" && m[2] === "release") return null; // the release commit itself
  return {
    hash,
    author: author.trim(),
    type,
    scope: m[2] || null,
    breaking: Boolean(m[3]) || /BREAKING CHANGE/.test(m[4]),
    subject: m[4].trim(),
    pr: pr ? Number(pr[1]) : null,
  };
}

function sectionOf(c) {
  if (c.breaking) return "breaking";
  if (c.type === "feat" || c.type === "fix" || c.type === "perf") return c.type;
  return "other";
}

function draft(lines, { version = "Unreleased", date = "", repoUrl = "", all = false } = {}) {
  const commits = lines.map(parseLine).filter(Boolean);
  const groups = new Map(SECTIONS.map(([k]) => [k, []]));
  for (const c of commits) groups.get(sectionOf(c)).push(c);

  const ref = (c) => (c.pr ? (repoUrl ? ` ([#${c.pr}](${repoUrl}/pull/${c.pr}))` : ` (#${c.pr})`) : ` (${c.hash})`);
  const bullet = (c) => `- ${c.scope ? `**${c.scope}:** ` : ""}${c.subject}${ref(c)}`;

  const out = [`## ${version}${date ? ` — ${date}` : ""}`];
  for (const [key, title] of SECTIONS) {
    const list = groups.get(key);
    if (list.length === 0 || (key === "other" && !all)) continue;
    out.push("", `### ${title}`, "", ...list.map(bullet));
  }

  const hidden = all ? 0 : groups.get("other").length;
  if (hidden) out.push("", `_${hidden} other commit(s) (docs, chores, refactors, or not in Conventional Commits format) hidden — use --all to include them._`);

  // Names, not @handles: a draft shouldn't notify people before it's published.
  const people = [...new Set(commits.map((c) => c.author))].sort((a, b) => a.localeCompare(b));
  if (people.length) out.push("", `Thanks to ${people.join(", ")}.`);
  if (commits.length === 0) out.push("", "_No changes found in this range._");
  return out.join("\n");
}

module.exports = { parseLine, sectionOf, draft };

const test = require("node:test");
const assert = require("node:assert");
const { parseLine, draft } = require("../src/notes");

test("parses type, scope, breaking marker and PR number", () => {
  assert.deepStrictEqual(parseLine("a1\tAda\tfeat(cart)!: drop legacy coupons (#12)"), {
    hash: "a1",
    author: "Ada",
    type: "feat",
    scope: "cart",
    breaking: true,
    subject: "drop legacy coupons",
    pr: 12,
  });
  assert.strictEqual(parseLine("b2\tTom\tfixed a typo").type, null);
});

test("merge commits, release commits and blank lines are ignored", () => {
  assert.strictEqual(parseLine("c3\tTom\tMerge pull request #4 from tom/x"), null);
  assert.strictEqual(parseLine("d4\tAda\tchore(release): v1.2.0"), null);
  assert.strictEqual(parseLine(""), null);
});

test("draft groups commits, links PRs and hides other changes by default", () => {
  const md = draft(
    [
      "a1\tAda\tfeat(cart): coupons (#1)",
      "b2\tTom\tfix: declined card message (#2)",
      "c3\tLin\tdocs: readme",
      "d4\tPriya\tfeat!: new search (#3)",
    ],
    { version: "v1.3.0", date: "2026-10-15", repoUrl: "https://github.com/acme/shop" }
  );
  assert.match(md, /^## v1\.3\.0 — 2026-10-15/);
  assert.match(md, /### ⚠️ Breaking changes\n\n- new search \(\[#3\]\(https:\/\/github\.com\/acme\/shop\/pull\/3\)\)/);
  assert.match(md, /### Features\n\n- \*\*cart:\*\* coupons/);
  assert.match(md, /### Fixes\n\n- declined card message/);
  assert.ok(!md.includes("### Other changes"));
  assert.match(md, /1 other commit\(s\).*hidden/);
});

test("--all shows other changes; contributors are thanked by name without @", () => {
  const md = draft(["a1\tAda\tdocs: readme", "b2\tTom\trefactor: tidy"], { all: true });
  assert.match(md, /### Other changes\n\n- readme \(a1\)\n- tidy \(b2\)/);
  assert.match(md, /Thanks to Ada, Tom\./);
  assert.ok(!md.includes("@"));
});

test("an empty range says so", () => {
  assert.match(draft([""]), /No changes found/);
});
